"""Lifestyle photos: a person wearing the cap, generated by the Gemini image model from the flat layout.
Illustration only: the model redraws the print approximately; print from the stencils, not from these.

python3 tools/on_model.py                      # all designs listed in WHO
python3 tools/on_model.py kids_boy_dino_surf   # selected slugs
Output: on_model/<slug>_on_model.jpg
"""
import os, io, json, sys
from concurrent.futures import ThreadPoolExecutor
from PIL import Image
from google import genai
from google.genai import types
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
D = os.path.join(ROOT, 'designs'); OUT = os.path.join(ROOT, 'on_model'); os.makedirs(OUT, exist_ok=True)
MODEL = os.environ.get('GEMINI_IMAGE_MODEL', 'gemini-3-pro-image')
WHO = {
 'leaves_refraction_navy': 'an athletic adult swimmer (man) standing at the edge of an outdoor pool, adjusting goggles',
 'kids_boy_dino_surf': 'a happy 7-year-old boy in a bright indoor kids pool, laughing, holding a kickboard',
 'kids_boy_sub_robots': 'a cheerful 8-year-old boy sitting on the pool edge, thumbs up, splashing feet',
 'kids_girl_mermaid_cats': 'a joyful 6-year-old girl in a sunny pool, popping up from the water with a big smile',
 'kids_girl_jelly_party': 'a smiling 8-year-old girl at a swimming lesson, holding goggles, pool background',
 'uni_slavic_sport': 'a fit competitive swimmer (woman) on a starting block in a 50 m pool, focused, sporty look',
 'fem_peony_waves': 'an elegant woman with long hair tucked inside the long swim cap, at a calm outdoor pool at golden hour',
 'fem_pearl_jellyfish': 'a graceful woman with long hair tucked inside the long swim cap, in the sea at dusk, shoulders above water',
 'fem_peony_waves_light': 'an elegant woman with long hair tucked inside the long swim cap, at a bright pool with white tiles, morning light',
 'fem_pearl_jellyfish_light': 'a graceful woman with long hair tucked inside the long swim cap, in clear turquoise sea, sunny day',
}
PROMPT = ("Photorealistic lifestyle photo for a swimwear catalogue: {who}, wearing a silicone swim cap. "
          "The cap is solid {base_name} silicone ({base_hex}) and carries EXACTLY the printed pattern "
          "from the attached flat layout image, including the BRAND logo on the side, wrapped naturally around the head with "
          "realistic curvature, slight silicone sheen and water droplets. Keep the print colours and motifs faithful to the reference. "
          "Natural skin, natural light, shallow depth of field, no other text or logos, 4:5 portrait.")
sys.path.insert(0, os.path.join(ROOT, 'lib'))
from gemini_gen import make_client
c = make_client()

def run(slug):
    spec = json.load(open(f'{D}/{slug}/_gemini/spec.json'))
    p = f'{D}/{slug}/PNG/{slug}_side-A_layout.png'
    ref = Image.open(p if os.path.exists(p) else f'{D}/{slug}/{slug}_side-A_layout.png').convert('RGB')
    p = PROMPT.format(who=WHO[slug], base_name=spec['base']['name'], base_hex=spec['base']['hex'])
    err = 'no image'
    for _ in range(2):
        try:
            r = c.models.generate_content(model=MODEL, contents=[p, ref],
                config=types.GenerateContentConfig(response_modalities=['IMAGE'], image_config=types.ImageConfig(aspect_ratio='4:5')))
            for part in r.candidates[0].content.parts:
                if part.inline_data is not None:
                    Image.open(io.BytesIO(part.inline_data.data)).convert('RGB').save(f'{OUT}/{slug}_on_model.jpg', quality=90)
                    return slug, 'ok'
        except Exception as e:
            err = str(e)[:200]
    return slug, 'fail ' + err

if __name__ == '__main__':
    slugs = sys.argv[1:] or list(WHO)
    with ThreadPoolExecutor(5) as ex:
        for res in ex.map(run, slugs): print(*res, flush=True)
